// transfer_to_human — Validate Input
// Expected body: { business_id, call_id, caller_number, transfer_reason }
//
// transfer_reason must resolve to one of a fixed, universal set of
// approved categories -- this workflow never approves a transfer for an
// arbitrary free-text reason. See config/business-profile.example.json's
// transfer_rules.universal_triggers for where these categories come from.
const REASONS = {
  explicit_human_request: 'explicit_human_request',
  human_request: 'explicit_human_request',
  human: 'explicit_human_request',
  person: 'explicit_human_request',
  emergency_or_distress: 'emergency_or_distress',
  emergency: 'emergency_or_distress',
  distress: 'emergency_or_distress',
  complaint: 'complaint',
  payment_dispute: 'payment_dispute',
  billing_dispute: 'payment_dispute',
  payment: 'payment_dispute',
  unknown_or_sensitive_question: 'unknown_or_sensitive_question',
  unknown_question: 'unknown_or_sensitive_question',
  restricted_question: 'unknown_or_sensitive_question',
  restricted_topic: 'unknown_or_sensitive_question',
  sensitive_question: 'unknown_or_sensitive_question',
};

const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const callId = String(body.call_id ?? '').trim();
const callerNumber = String(body.caller_number ?? '').trim();
const rawReason = String(body.transfer_reason ?? '').trim();

const transferReason = REASONS[rawReason.toLowerCase().replace(/\s+/g, '_')] || null;

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!callId) errors.push('call_id is required');

const callerDigits = callerNumber.replace(/\D/g, '');
if (!callerNumber) {
  errors.push('caller_number is required');
} else if (callerDigits.length < 7 || callerDigits.length > 15) {
  errors.push('caller_number must contain 7-15 digits');
}

if (!rawReason) {
  errors.push('transfer_reason is required');
} else if (!transferReason) {
  errors.push('transfer_reason must be one of: explicit_human_request, emergency_or_distress, complaint, payment_dispute, unknown_or_sensitive_question');
}

// call_id doubles as the link to a Supabase `calls` row, if one exists
// yet, for logging -- but transfer_to_human typically fires mid-call,
// before log_call has created that row (see the sticky note above). Only
// attempt that lookup when call_id is actually UUID-shaped; caller_number
// itself is validated but deliberately never persisted anywhere below.
const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    call_id: callId || null,
    call_id_is_uuid: UUID_RE.test(callId),
    transfer_reason: transferReason,
  },
}];

const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;
return [{ json: { business_found: !!row, business_id: row ? row.id : null } }];

// Normalize Settings
// No settings row (business exists but hasn't been configured yet) means
// no transfer number -- falls back to the callback path, never a guess.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.business_id ? items[0].json : null;

return [{ json: { transfer_number: row ? row.transfer_number : null } }];

// transfer_to_human — Build Decision
// The only per-business "approved transfer setting" this schema stores is
// business_settings.transfer_number. transfer_reason itself was already
// validated against a fixed, universal set of categories in "Validate
// Input" -- this template does not let a business enable/disable
// individual reason categories; every business shares the same universal
// transfer triggers (config/business-profile.example.json's
// transfer_rules.universal_triggers).
//
// A still-unconfigured business ships with the seed/onboarding
// placeholder ("REPLACE_WITH_..."), which must be treated exactly like
// "no number configured" -- never dialled or read back to a caller.
const input = $('Validate Input').first().json;
const settings = $('Normalize Settings').first().json;

const rawNumber = settings.transfer_number;
const configured = !!rawNumber && !String(rawNumber).toUpperCase().startsWith('REPLACE_WITH');

return [{
  json: {
    business_id: input.business_id_input,
    call_id: input.call_id,
    reason: input.transfer_reason,
    decision: configured ? 'transfer_approved' : 'callback_fallback',
    transfer_number: configured ? rawNumber : null,
    message: configured
      ? 'Transfer approved for an approved reason. Connect the caller to this business\'s transfer number now.'
      : 'No transfer number is configured for this business yet. Do not attempt a transfer -- use create_callback_request instead so the business can follow up.',
  },
}];

const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;
return [{ json: { call_found: !!row } }];

// transfer_to_human — Build Final Response
// Reached from four different paths (non-UUID call_id, lookup failed,
// call not found, or the insert itself succeeding/failing) -- try/catch
// against specific node names (the standard idiom used throughout this
// repo for "read a node that may not have executed this run") figures
// out which one actually happened without needing four near-duplicate
// response builders.
const decision = $('Build Decision').first().json;

let logged = 'skipped_non_uuid_call_id';
try {
  $('Get Call For Logging').first();
  // The lookup node ran, so a lookup was attempted.
  try {
    const lookup = $('Normalize Call Lookup').first().json;
    logged = lookup && lookup.call_found ? 'pending' : 'call_not_found';
  } catch (e) {
    logged = 'lookup_failed';
  }
  try {
    const inserted = $('Insert Call Event').first().json;
    logged = inserted && inserted.id ? 'logged' : 'failed';
  } catch (e) {
    // Insert Call Event never ran (call_not_found path) -- `logged` keeps
    // whatever the lookup step above already set.
  }
} catch (e) {
  logged = 'skipped_non_uuid_call_id';
}

return [{
  json: {
    business_id: decision.business_id,
    call_id: decision.call_id,
    decision: decision.decision,
    reason: decision.reason,
    transfer_number: decision.transfer_number,
    message: decision.message,
    logged,
  },
}];
